package com.gbconnected.kpivalidation.functions;
import com.gbconnected.kpivalidation.application.*;
import com.gbconnected.kpivalidation.application.approval.*;
import com.google.gson.*;
import com.microsoft.azure.functions.*;import com.microsoft.azure.functions.annotation.*;
import java.util.*;
public class KpiApprovalFunctions {
 private static final String CORRELATION="X-Correlation-Id";
 @FunctionName("kpi-approval-pending") public HttpResponseMessage pending(@HttpTrigger(name="req",methods={HttpMethod.GET},route="v1/kpi-approval/pending",authLevel=AuthorizationLevel.FUNCTION)HttpRequestMessage<Optional<String>> req,ExecutionContext ctx){String c=correlation(req);try{var result=FunctionRuntime.RUNTIME.kpiApproval().pending(FunctionActorContextResolver.resolve(req));ctx.getLogger().info("event=kpi_approval_pending_open correlationId="+c+" resultCount="+result.size());return json(req,HttpStatus.OK,result,c);}catch(Exception e){return reject(req,e,c);}}
 @FunctionName("kpi-approval-list") public HttpResponseMessage list(@HttpTrigger(name="req",methods={HttpMethod.GET},route="v1/kpi-approval/validations",authLevel=AuthorizationLevel.FUNCTION)HttpRequestMessage<Optional<String>> req,ExecutionContext ctx){String c=correlation(req);try{Map<String,String>q=req.getQueryParameters();String status=q.get("status"),domain=q.get("domain");Long plant=q.get("plantId")==null?null:Long.valueOf(q.get("plantId"));java.time.LocalDate from=q.get("fromDate")==null?null:java.time.LocalDate.parse(q.get("fromDate"));java.time.LocalDate to=q.get("toDate")==null?null:java.time.LocalDate.parse(q.get("toDate"));int offset=q.get("offset")==null?0:Integer.parseInt(q.get("offset"));int limit=q.get("limit")==null?50:Integer.parseInt(q.get("limit"));var result=FunctionRuntime.RUNTIME.kpiApproval().list(FunctionActorContextResolver.resolve(req),new ApprovalValidationQuery(status,domain,plant,from,to,offset,limit));ctx.getLogger().info("event=kpi_approval_list correlationId="+c+" resultCount="+result.items().size()+" total="+result.total());return json(req,HttpStatus.OK,result,c);}catch(Exception e){return reject(req,e,c);}}
 @FunctionName("kpi-approval-detail") public HttpResponseMessage get(@HttpTrigger(name="req",methods={HttpMethod.GET},route="v1/kpi-approval/validations/{id}",authLevel=AuthorizationLevel.FUNCTION)HttpRequestMessage<Optional<String>> req,@BindingName("id")long id,ExecutionContext ctx){String c=correlation(req);try{var result=FunctionRuntime.RUNTIME.kpiApproval().get(FunctionActorContextResolver.resolve(req),id);ctx.getLogger().info("event=kpi_approval_review correlationId="+c+" validationId="+id+" status="+result.status());return json(req,HttpStatus.OK,result,c);}catch(Exception e){return reject(req,e,c);}}
 @FunctionName("kpi-approval-decision") public HttpResponseMessage decide(@HttpTrigger(name="req",methods={HttpMethod.POST},route="v1/kpi-approval/validations/{id}/decision",authLevel=AuthorizationLevel.FUNCTION)HttpRequestMessage<Optional<String>> req,@BindingName("id")long id,ExecutionContext ctx){String c=correlation(req);try{JsonObject b=JsonParser.parseString(req.getBody().orElseThrow(()->new IllegalArgumentException("JSON body is required"))).getAsJsonObject();ApprovalDecision d=ApprovalDecision.valueOf(b.get("decision").getAsString().trim().toUpperCase(Locale.ROOT));var result=FunctionRuntime.RUNTIME.kpiApproval().decide(FunctionActorContextResolver.resolve(req),id,d,c);ctx.getLogger().info("event=kpi_approval_decision correlationId="+c+" validationId="+id+" decision="+d+" status="+result.status());return json(req,HttpStatus.OK,result,c);}catch(Exception e){return reject(req,e,c);}}
 @FunctionName("kpi-approval-policy") public HttpResponseMessage policy(@HttpTrigger(name="req",methods={HttpMethod.GET},route="v1/kpi-approval/policy",authLevel=AuthorizationLevel.FUNCTION)HttpRequestMessage<Optional<String>> req,ExecutionContext ctx){return json(req,HttpStatus.OK,FunctionRuntime.RUNTIME.kpiApproval().policy(),correlation(req));}
 private static HttpResponseMessage reject(HttpRequestMessage<?>r,Exception e,String c){HttpStatus s=e instanceof SecurityException?HttpStatus.UNAUTHORIZED:e instanceof AuthorizationException?HttpStatus.FORBIDDEN:e instanceof ApprovalNotFoundException?HttpStatus.NOT_FOUND:e instanceof ApprovalConflictException?HttpStatus.CONFLICT:HttpStatus.BAD_REQUEST;return r.createResponseBuilder(s).header(CORRELATION,c).header("Content-Type","application/json").body(JsonCodec.GSON.toJson(Map.of("error",e.getMessage()==null?"Request rejected":e.getMessage()))).build();}
 private static HttpResponseMessage json(HttpRequestMessage<?>r,HttpStatus s,Object b,String c){return r.createResponseBuilder(s).header(CORRELATION,c).header("Content-Type","application/json").body(JsonCodec.GSON.toJson(b)).build();}
 private static String correlation(HttpRequestMessage<?>r){return r.getHeaders().entrySet().stream().filter(e->e.getKey().equalsIgnoreCase(CORRELATION)).map(Map.Entry::getValue).findFirst().filter(v->!v.isBlank()).orElse(UUID.randomUUID().toString());}
}
